(191,	'_elementor_notifications_data',	'a:2:{s:7:\"timeout\";i:1787344767;s:5:\"value\";s:15663:\"[{\"id\":\"webinar-cinematic-scroll-mcp-rewatch\",\"title\":\"Webinar rewatch: Cinematic scroll & MCP teaser\",\"description\":\"See how to generate a full page from simple prompts, add an immersive cinematic scroll experience to your site and get a first look at the Elementor MCP that\'s coming soon.\",\"topic\":\"Webinar\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/webinar-cinematic-scroll-mcp.png\",\"chipTags\":[\"Webinar\"],\"link\":\"https:\\/\\/www.youtube.com\\/watch?v=qyr0VGwpA8I\",\"readMoreText\":\"Learn more\"},{\"id\":\"angie-build-cover-v2\",\"title\":\"Vibe-code pages, design systems, and more\",\"description\":\"Generate complete layouts and individual sections from a plain-language description, matched to your site\'s design. Build native design systems, dynamic loops, and forms as real Elementor structure, fully editable in the visual Editor. Preview safely before anything goes live.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-cover.png\",\"youtubeEmbedId\":\"QQy5Y7QNHgM\",\"youtubeAutoplay\":true,\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-full-page\",\"title\":\"Generate full Elementor pages\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. Every result can be matched to your site\'s existing styles or follow any new design instructions you give.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-full-page.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-design-system\",\"title\":\"Turn a screenshot into a design system\",\"description\":\"Describe your site\'s look, upload a screenshot, or paste your values, and get a base design system built automatically: colors and typography as reusable variables and classes or global styles. Every layout Angie builds draws from the same system, so new pages stay consistent.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-design-system.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-loop\",\"title\":\"Generate forms and loops from a sentence\",\"description\":\"Generate dynamic content loops and forms from a description. Give Angie the fields and layout you need, and it builds a real Atomic Form, composable and ready to style. Ask for a Loop and Angie builds the dynamic archive, layout, items, and pagination.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-loop.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-super-community\",\"title\":\"Angie Community Library\",\"description\":\"Browse a library of snippets and widgets built by other Angie users, import any of them into your site, without consuming any credits or remix them with a prompt to match your brief. Every snippet is vetted by the Elementor team. You can also submit your own work for the community to discover.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/\",\"readMoreText\":\"Browse library\"},{