(2285,	210,	'_elementor_data',	'[{\"id\":\"4c589b3f\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"167a4dab\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<!-- wp:group {\\\"layout\\\":{\\\"type\\\":\\\"flex\\\",\\\"flexWrap\\\":\\\"nowrap\\\"}} -->\\n<div class=\\\"wp-block-group\\\"><!-- wp:image {\\\"id\\\":202,\\\"sizeSlug\\\":\\\"large\\\",\\\"linkDestination\\\":\\\"none\\\"} -->\\n<figure class=\\\"wp-block-image size-large\\\"><img class=\\\"wp-image-202\\\" src=\\\"http:\\/\\/marclesterbagal.local\\/wp-content\\/uploads\\/2026\\/08\\/ProperPicture-1-706x1024.jpg\\\" alt=\\\"\\\" \\/><\\/figure>\\n<!-- \\/wp:image --><!-- wp:group {\\\"layout\\\":{\\\"type\\\":\\\"constrained\\\"}} -->\\n<div class=\\\"wp-block-group\\\"><!-- wp:heading -->\\n<h2 class=\\\"wp-block-heading\\\">About Me<\\/h2>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>I am a computer science student with a deep focus on front-end development and user experience design. I believe in crafting interfaces that are not only visually striking but inherently intuitive.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:paragraph -->\\n<p>My approach merges analytical problem-solving with creative design principles, aiming to deliver polished, high-performance web applications that leave a lasting impact.<\\/p>\\n<!-- \\/wp:paragraph --><\\/div>\\n<!-- \\/wp:group --><\\/div>\\n<!-- \\/wp:group --><!-- wp:paragraph -->\\n<p>\\u00a0<\\/p>\\n<!-- \\/wp:paragraph -->\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}]'),
