(240,	1,	'2026-08-13 04:06:32',	'2026-08-13 04:06:32',	'<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<!-- wp:image {\"id\":202,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure><img src=\"http://marclesterbagal.local/wp-content/uploads/2026/08/ProperPicture-1-706x1024.jpg\" alt=\"\" /></figure>\n<!-- /wp:image --><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<!-- wp:heading -->\n<h2>About Me</h2>\n<!-- /wp:heading --><!-- wp:paragraph -->\n<p>I am a computer science student with a deep focus on front-end development and user experience design. I believe in crafting interfaces that are not only visually striking but inherently intuitive.</p>\n<!-- /wp:paragraph --><!-- wp:paragraph -->\n<p>My approach merges analytical problem-solving with creative design principles, aiming to deliver polished, high-performance web applications that leave a lasting impact.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:group -->\n<!-- /wp:group --><!-- wp:paragraph -->\n<p> </p>\n<!-- /wp:paragraph -->',	'About',	'',	'inherit',	'closed',	'closed',	'',	'16-revision-v1',	'',	'',	'2026-08-13 04:06:32',	'2026-08-13 04:06:32',	'',	16,	'http://marclesterbagal.local/?p=240',	0,	'revision',	'',	0),
